T("A Suite look, font, minimum height and position for Blizzard dialogs, marked resurrection offers, the item quality written on loot toasts and gold-framed money toasts.", "Aspecto, fuente, altura mínima y posición de la Suite para los diálogos de Blizzard, ofertas de resurrección marcadas, la calidad del objeto escrita en los avisos de botín y avisos de dinero con marco dorado.")
