T("A channel plays a sound kit ID or a sound file (the file wins) for new messages. A burst plays once. Whisper is under Chat tools.", "Cada canal reproduce un kit de sonido o un archivo de sonido al recibir mensajes nuevos; el archivo tiene prioridad. Una ráfaga de mensajes suena una sola vez. Los susurros están en Herramientas de chat.")
T("A cinematic Suite screen with your character while you are AFK. Move or use /afk to return.", "Una pantalla cinemática de la Suite con tu personaje mientras estás ausente (AFK). Muévete o usa /afk para volver.")
T("A class in your group can provide this buff.", "Una clase de tu grupo puede proporcionar este beneficio.")
T("A clean minimap in its own frame: size, shape, border, zoom, Blizzard buttons, an addon button drawer and information texts. Blizzard's minimap buttons keep working.", "Un minimapa limpio en su propio marco: tamaño, forma, borde, zoom, botones de Blizzard, un cajón de botones de addons y textos informativos. Los botones del minimapa de Blizzard siguen funcionando.")
T("A click-through surface follows each Blizzard chat window. Blizzard and MSUF Edit Mode keep their normal move and resize controls.", "Una superficie que deja pasar los clics sigue cada ventana de chat de Blizzard. El modo de edición de Blizzard y el de MSUF conservan sus controles normales para mover y cambiar el tamaño.")
T("A colored plate sits behind the map and its border. Padding extends it beyond the map edge.", "Una placa de color se ubica detrás del mapa y de su borde. El relleno la extiende más allá del borde del mapa.")
T("A compact clock, FPS and latency bar.", "Una barra compacta de reloj, FPS y latencia.")
T("A compact, movable history of your recent successful spells.", "Un historial compacto y movible de tus últimos hechizos lanzados con éxito.")
T("A frame-rate readout can sit below the strip or on its own, placed in MSUF Edit Mode. The MSUF Suite FPS key binding shows or hides it for this session, in combat too; a new choice here replaces that session switch.", "Un indicador de cuadros puede ir debajo de la barra o aparte, colocado en el modo de edición de MSUF. El atajo de teclado de FPS de MSUF Suite lo muestra u oculta durante esta sesión, también en combate; una nueva elección aquí reemplaza ese cambio de sesión.")
T("A group member died", "Ha muerto un miembro del grupo")
T("A movable strip for critical strike, haste, mastery and versatility.", "Una barra movible para golpe crítico, celeridad, maestría y versatilidad.")
T("A movable summary after a Mythic+ run or raid boss kill.", "Un resumen movible tras un recorrido de Mítica+ o derrotar a un jefe de banda.")
T("A name cannot contain the | character.", "El nombre no puede contener el carácter |.")
T("A ring around the mouse pointer that is easy to spot, optionally filled by your global cooldown or cast.", "Un anillo bien visible alrededor del puntero del mouse, que puede rellenarse con tu tiempo de reutilización global o tu lanzamiento.")
T("A ring around the mouse pointer that makes it easy to find. Pick its shape, size, color, an optional short trail and a centre dot; No ring keeps only the dot or the progress fill. The camera mode shows ring, dot and trail only while you hold a mouse button down on the game world to turn the camera. The highlight follows the pointer only while something is shown, and it moves nothing while the pointer rests.", "Un anillo alrededor del puntero del mouse para encontrarlo con facilidad. Elige su forma, tamaño, color, una estela corta y un punto central; «Sin anillo» deja solo el punto o el relleno de progreso. El modo cámara muestra anillo, punto y estela solo mientras mantienes presionado un botón del mouse sobre el mundo del juego para girar la cámara. El resaltado sigue al puntero solo mientras se muestra algo y no mueve nada mientras el puntero está quieto.")
T("A secure fishing key with optional rod, lure and a temporary sound profile.\nSet Fishing and Apply fishing lure under Keybindings > MSUF Suite.\nEach action requires your key press; interacting with the bobber stays manual.", "Una tecla de pesca segura con caña, carnada y perfil de sonido temporal opcionales.\nAsigna Pesca y Aplicar carnada de pesca en Teclado > MSUF Suite.\nCada acción requiere pulsar una tecla; debes interactuar con el flotador manualmente.")
T("A sequence uses one condition rule", "Una secuencia usa una regla de condiciones")
T("A small panel beside the Group Finder search results. Its Search filters button saves your difficulty, minimum leader rating, role and dungeon choices in Blizzard's advanced search filter for your next manual search. Use Blizzard's Search button to search. It works on dungeon searches at maximum level, outside combat, and signs you up for nothing.", "Un pequeño panel junto a los resultados del buscador de grupos. Su botón Filtros de búsqueda guarda la dificultad, la valoración mínima del líder, las funciones y las mazmorras elegidas en el filtro avanzado de Blizzard para tu próxima búsqueda manual. Usa el botón Buscar de Blizzard para buscar. Funciona en búsquedas de mazmorras al nivel máximo, fuera de combate, y no te inscribe en nada.")
T("A small summary sits beside the Character tab of your character sheet and leaves with it. It lists your gear with gem sockets and how many are filled, open ones in amber (click a line to open socketing), the total durability of your gear and, if you like, your PvP item level. Its buttons open the Great Vault and the current expansion page. It updates while the sheet is open, at most once per frame.", "Un pequeño resumen se ubica junto a la pestaña Personaje de tu hoja de personaje y desaparece con ella. Muestra tu equipo con ranuras de gema y cuántas están llenas, las abiertas en ámbar (haz clic en una línea para engarzar), la durabilidad total de tu equipo y, si quieres, tu nivel de objeto JcJ. Sus botones abren la Gran Cámara y la página de la expansión actual. Se actualiza mientras la hoja está abierta, como máximo una vez por cuadro.")
T("A snapshot of current keys and loaded Suite action bars. Refresh after changing actions, forms or bindings.", "Vista de las teclas actuales y barras de Suite cargadas. Actualiza tras cambiar acciones, formas o asignaciones.")
T("A soft light behind the map, independent of the border and artwork.", "Una luz suave detrás del mapa, independiente del borde y del arte.")
T("A summary with gem sockets, durability, PvP item level and Great Vault and expansion buttons, durability on the model, cropped slot icons and item levels on equipment choices.", "Un resumen con ranuras de gema, durabilidad, nivel de objeto JcJ y botones de la Gran Cámara y la expansión, durabilidad sobre el modelo, íconos de ranura recortados y niveles de objeto en la selección de equipo.")
T("A valid spell name does not confirm a matching target aura. Custom IDs remain selected until you disable them.", "Un nombre de hechizo válido no confirma un aura del objetivo. Los IDs personalizados siguen seleccionados hasta desactivarlos.")
T("A waypoint cannot be set on this map", "No se puede establecer un punto de ruta en este mapa")
