T("Accept only ordinary party invitations from the relationship types you select. Invites remain manual in combat, while grouped, during queue-loss or quest-session confirmations, or when Blizzard asks you to choose a role. The native popup handles the final action.", "Acepta únicamente las invitaciones normales a grupos de los tipos de contacto que elijas. La aceptación seguirá siendo manual en combate, si ya estás en un grupo, cuando pudiera perderse una cola o confirmación de misión, o si Blizzard te pide elegir un rol. La ventana nativa realiza la acción final.")
