T("An adjacent button opens a small menu for expansion, Great Vault, Adventure Guide and world map pages. Blizzard's landing button keeps its own click behavior. Menu actions are disabled in combat.", "Un botón junto al de Blizzard abre un pequeño menú con la página de la expansión, la Gran Cámara, la Guía de aventuras y el mapa del mundo. El botón original de Blizzard mantiene su función. Las acciones del menú no están disponibles en combate.")
T("An empty allow-list includes every quest. Separate quest IDs with spaces or commas. Daily and weekly exclusions leave a quest manual if its frequency cannot be read. Existing profiles keep their previous behavior until you enable an exclusion.", "Una lista de permitidas vacía incluye todas las misiones. Separa los ID de misión con espacios o comas. Las exclusiones diarias y semanales dejan una misión en manual si no se puede leer su frecuencia. Los perfiles existentes mantienen su comportamiento anterior hasta que actives una exclusión.")
