T("Apply a graphics preset once. Balanced changes your general settings and keeps your separate raid settings.\nRaid / Dungeon changes only the separate instance settings and enables them.\nTextures, particle density and outlines stay as you set them; projected textures stay on. Unsupported settings are skipped.\nSharpening, contrast and audio reverb are optional and apply globally.\nYour originals are saved outside profiles. Restore keeps later manual changes. FPS gains depend on your hardware and the scene.", "Aplica un preajuste gráfico una sola vez. Equilibrado cambia los ajustes generales y conserva los ajustes separados de banda.\nBanda / Mazmorra cambia solo los ajustes separados de instancia y los activa.\nLas texturas, la densidad de partículas y los contornos se mantienen como los configuraste; las texturas proyectadas siguen activadas. Se omiten los ajustes no compatibles.\nLa nitidez, el contraste y la reverberación de audio son opcionales y se aplican globalmente.\nLos valores originales se guardan fuera de los perfiles. Restaurar conserva los cambios manuales posteriores. La mejora de FPS depende del equipo y de la escena.")
