T("Blizzard's distance and stacking options. Keep Blizzard setting changes nothing; other choices return to Blizzard's value when the skin turns off.", "Opciones de distancia y apilamiento de Blizzard. Mantener el ajuste de Blizzard no cambia nada; las demás opciones restauran el valor de Blizzard al desactivar el aspecto.")
T("Blizzard's entry for this spell is already on this bar.", "La entrada de Blizzard para este hechizo ya está en esta barra.")
