T("Center keeps the whole visible cooldown row centered as icons appear or disappear. Enable Keep first icon centered for alternating growth around the first icon. Buff icons then keep fixed places, with gaps for inactive buffs. Attach the bar to another bar or to your player frame; Gap controls the space between them.", "Centro mantiene centrada toda la fila visible de tiempos de reutilización cuando aparecen o desaparecen iconos. Activa Mantener centrado el primer icono para crecer alternando alrededor del primero. Los iconos de beneficios conservan posiciones fijas, con huecos para los beneficios inactivos. Ancla la barra a otra barra o al marco de tu personaje; Separación controla el espacio entre ellos.")
