T("Clean Modern is the Retail default; MSUF Forever is the Forever default. Midnight Blue keeps the original blue glass. Open a section's three-dot menu to change its colors, or use MSUF Colors for the full palette. Your own color changes become Custom.", "Limpio y moderno es el estilo predeterminado de Retail; MSUF Forever es el de Forever. Midnight Blue conserva el cristal azul original. Abre el menú de tres puntos de una sección para cambiar sus colores o usa Colores de MSUF para toda la paleta. Tus cambios de color pasan a ser Personalizado.")
T("Clean Modern uses matte panels with white accents. Midnight Blue keeps the original blue palette. Midnight Dark uses neutral charcoal glass; MSUF Forever retains its muted gold. Color changes become Custom.", "Limpio y moderno usa paneles mates con detalles blancos. Midnight Blue conserva la paleta azul original. Midnight Dark usa cristal gris carbón neutro; MSUF Forever mantiene su dorado suave. Los cambios de color pasan a ser Personalizado.")
T("Clean Modern, Midnight Blue, Midnight Dark and MSUF Forever are complete looks in Style. Color palettes here change colors only; use Expert mode for every UI state.", "Limpio y moderno, Midnight Blue, Midnight Dark y MSUF Forever son aspectos completos en Estilo. Aquí las paletas de color solo cambian los colores; usa el modo Experto para cada estado de la interfaz.")
