T("Critical strike, haste, mastery and versatility as your character sheet shows them; leech, avoidance and speed can each join the strip (speed is the stat, not your running speed). Show only in combat hides the strip outside fights. Values the game hides show a dash, and the strip updates from your stat events. MSUF Edit Mode moves the strip.", "Golpe crítico, celeridad, maestría y versatilidad como las muestra tu hoja de personaje; restitución, evitación y velocidad pueden unirse cada una a la barra (la velocidad es el atributo, no tu velocidad de carrera). Mostrar solo en combate oculta la barra fuera de los combates. Los valores que el juego oculta muestran un guion y la barra se actualiza con los eventos de tus atributos. El modo de edición de MSUF mueve la barra.")
