T("Dark panel keeps the bank's usual color for the Suite bank views; Match the bag window follows the bag background color and look. The panel stays opaque so Blizzard's own slots never show through it. The size and position apply to the whole bank window, also in Bank tabs. Move the open bank in MSUF Edit Mode, or set the offsets here after turning on the custom position.", "Panel oscuro conserva el color habitual del banco en las vistas de la Suite; Igualar a la ventana de bolsas usa el color y estilo de las bolsas. El panel permanece opaco para ocultar las casillas de Blizzard situadas detrás. El tamaño y la posición afectan a toda la ventana del banco, también con pestañas nativas. Mueve el banco abierto en el modo de edición de MSUF o activa la posición personalizada y ajusta aquí los desplazamientos.")
