T("Docked timers follow the selected window and hide with it. Positive horizontal offsets move right; positive vertical offsets move up.", "Los temporizadores acoplados siguen la ventana elegida y se ocultan con ella. Los valores horizontales positivos mueven a la derecha; los verticales positivos, hacia arriba.")
