T("Double", "Doble")
T("Double-click a search result to open Blizzard's application dialog. With submit on double-click, the second click also signs up with the roles already chosen in that dialog; hold Shift to review it instead. A saved note can appear beside the dialog for copying; it is stored when you finish editing.", "Haz doble clic en un resultado de búsqueda para abrir la ventana de solicitud de Blizzard. Con el envío por doble clic, el segundo clic también te inscribe con los roles ya elegidos en esa ventana; mantén presionado Mayús para revisarla en su lugar. Una nota guardada puede aparecer junto a la ventana para copiarla; se guarda al terminar de editarla.")
T("Double-click a search result to open Blizzard's normal application dialog.", "Haz doble clic en un resultado de búsqueda para abrir la ventana normal de solicitud de Blizzard.")
T("Draft saved", "Borrador guardado")
T("Drag a window by its top edge; drag the bottom-right corner to scale it. The top-right minus button collapses compatible windows to a restore tab. Bags and protected windows keep their native behavior.", "Arrastra una ventana por su borde superior; arrastra la esquina inferior derecha para escalarla. El botón de menos de la esquina superior derecha contrae las ventanas compatibles a una pestaña de restauración. Las bolsas y las ventanas protegidas mantienen su comportamiento nativo.")
T("Drag announcements in MSUF Edit Mode, or set their timing, scale and exact position here.", "Arrastra los anuncios en el modo de edición de MSUF o define aquí su duración, escala y posición exacta.")
T("Drag or use arrows to move; Shift: 5, Ctrl: 10.", "Arrastra o usa las flechas para mover; Mayús: 5, Ctrl: 10.")
T("Drag or use arrows to move; click for settings.", "Arrastra o usa las flechas para mover; haz clic para ver los ajustes.")
T("Drag the bag title to move it; click for options.", "Arrastra el título de la bolsa para moverla; pulsa para ver opciones.")
T("Drag the bar's edge to move it on screen.", "Arrastra el borde de la barra para moverla en la pantalla.")
T("Drag the reagent bag title while it is open to move it independently. Click the title for bag options. Reset its position in MSUF Edit Mode to follow Blizzard's normal bag layout again.", "Arrastra el título de la bolsa de componentes mientras está abierta para moverla por separado. Haz clic en el título para ver las opciones de bolsa. Restablece su posición en el modo de edición de MSUF para que vuelva a seguir el diseño normal de bolsas de Blizzard.")
T("Drag the result card in MSUF Edit Mode, or set its screen anchor, width, scale and position here.", "Arrastra la tarjeta de resultados en el modo Edición de MSUF o ajusta aquí su anclaje, ancho, escala y posición.")
T("Drag the title of an open bag to move it. Click the title for bag options. Each bag keeps its own position. Blizzard shows your current gold on the right; the optional Session value on the left shows the change since login and survives /reload. Adjust the combined bag size here or in its MSUF Edit Mode popup. Reset position in Edit Mode returns the window to Blizzard's normal anchor.", "Arrastra el título de una bolsa abierta para moverla. Haz clic en el título para ver las opciones de bolsa. Cada bolsa mantiene su propia posición. Blizzard muestra tu oro actual a la derecha; el valor opcional Sesión a la izquierda muestra el cambio desde el inicio de sesión y sobrevive a /reload. Ajusta aquí el tamaño de las bolsas combinadas o en su ventana emergente del modo de edición de MSUF. Restablecer posición en el modo de edición devuelve la ventana al ancla normal de Blizzard.")
