T("Drop an item onto Pinned items in the category sidebar to keep it at the top of every view. Recent items lists up to 200 item types this character received, also across logins; each leaves the list once it is older than the hours set here, and Clear recent items empties it sooner. Neither action moves or deletes an item.", "Arrastra un objeto a Objetos fijados en la barra lateral para mantenerlo arriba en todas las vistas. Objetos recientes muestra hasta 200 tipos de objetos que este personaje recibió, también entre sesiones; cada uno sale de la lista cuando supera las horas indicadas aquí, y Borrar objetos recientes la vacía antes. Ninguna acción mueve ni elimina objetos.")
