T("Drops this bar's own order and the spells and items you added to it, for this specialization. Spells you removed stay hidden: Show removed spells brings them back. You can undo it.", "Descarta el orden propio de esta barra y los hechizos y objetos que le agregaste, para esta especialización. Los hechizos que quitaste siguen ocultos: Mostrar hechizos quitados los recupera. Puedes deshacerlo.")
