T("Each phrase may contain up to 80 characters.", "Cada frase puede contener hasta 80 caracteres.")
T("Each response is its own switch and none acts in combat. A summon that skips a starting area, and a resurrection during a boss encounter or while Blizzard makes you wait, stay yours. Party invite declines never touch friends, Battle.net friends or guild members, and invites that ask for a role or start a quest session stay yours. A chat line can report each response.", "Cada respuesta tiene su propio interruptor y nunca actúa en combate. Decides tú sobre invocaciones que omiten zonas iniciales y resurrecciones durante encuentros con jefes o esperas de Blizzard. Los rechazos de invitaciones de grupo nunca afectan a amigos, amigos de Battle.net ni miembros de la hermandad. También decides tú sobre invitaciones con selección de función o a sesiones de misiones. Cada respuesta puede anunciarse en el chat.")
T("Each specialization keeps its own bar layout: positions, attachments, growth, rows, spacing and sizes. Until it has its own, it uses the current one.", "Cada especialización guarda su propio diseño de barras: posiciones, anclajes, crecimiento, filas, espaciado y tamaños. Mientras no tenga uno propio, usa el actual.")
T("Each window keeps its own meter, fight, size and visibility rules. Drag the header or use MSUF Edit Mode to move it.", "Cada ventana mantiene sus propias reglas de medidor, combate, tamaño y visibilidad. Arrastra el encabezado o usa el modo de edición de MSUF para moverla.")
