T("Enter a spell name or ID on MSUF action bars. Its buttons glow from the aura and unit selected below. A page change in combat pauses the glow until combat ends.", "Ingresa el nombre o ID de un hechizo en las barras de MSUF. Sus botones se resaltan según el aura y la unidad elegidas abajo. Cambiar de página en combate pausa el resaltado hasta salir del combate.")
T("Enter a talent or spell name or ID, then press Enter. Every required spell must be learned. Empty removes this condition.", "Introduce el nombre o ID de un talento o hechizo y pulsa Intro. Debes conocer todos los hechizos requeridos. Deja el campo vacío para eliminar esta condición.")
T("Enter a talent or spell name or ID, then press Enter. The entry is hidden while any excluded spell is learned. Conditions update outside combat.", "Introduce el nombre o ID de un talento o hechizo y pulsa Intro. La entrada se oculta si conoces cualquiera de los hechizos excluidos. Las condiciones se actualizan fuera de combate.")
