T("Enter the cast spell's name or ID. Leave empty for automatic spell matching. Timers start only from readable player cast events.", "Introduce el nombre o ID del hechizo lanzado. Déjalo vacío para la asociación automática. Los temporizadores solo empiezan con eventos de lanzamiento legibles del jugador.")
T("Enter up to 200 item IDs. A button appears only at a merchant and previews eligible stacks; clicking it opens a confirmation. The helper checks item identity, quality, value, quest status and bag position again before requesting sales. Equippable items require a separate opt-in.", "Introduce hasta 200 ID de objeto. El botón aparece solo ante un vendedor y muestra los lotes válidos antes de abrir la confirmación. El asistente vuelve a comprobar la identidad, la calidad, el valor, el estado de misión y la posición en la bolsa antes de solicitar la venta. Para incluir objetos equipables debes activar otra opción.")
T("Enter up to eight spell IDs for movement abilities. When movement begins, the first known, ready and usable spell appears briefly; a shared 20-second cooldown limits notices. Empty IDs do no work. MSUF Edit Mode moves the cue.", "Introduce hasta ocho ID de hechizos de movimiento. Al empezar a moverte, aparece brevemente el primer hechizo conocido, disponible y utilizable; un tiempo de reutilización compartido de 20 segundos limita los avisos. Los campos vacíos no hacen nada. El modo de edición de MSUF mueve el aviso.")
