T("Every spell of this bar, unlearned ones included. On a buff bar, Add spells offers received buffs such as Power Infusion and Innervate; Buff on me also accepts a buff aura ID or resolvable name and tracks that ID from any caster. With Show missing buffs off, only active buffs appear. The preview edits entries too: click for options, drag to reorder or onto a bar above, middle-click to remove (with undo). Removed spells stay under Add spells. Lists are kept per specialization.", "Todos los hechizos de esta barra, incluidos los no aprendidos. En una barra de beneficios, Agregar hechizos ofrece beneficios recibidos como Infusión de poder y Estimular; Beneficio en mí también acepta un ID de aura de beneficio o un nombre reconocible y rastrea ese ID de cualquier lanzador. Con Mostrar beneficios faltantes desactivado, solo aparecen los beneficios activos. La vista previa también edita las entradas: haz clic para ver opciones, arrastra para reordenar o suelta sobre una barra de arriba, clic central para quitar (se puede deshacer). Los hechizos quitados quedan en Agregar hechizos. Las listas se guardan por especialización.")
