T("Font, text sizes and background opacity. The tracker colors are in this section's three-dot menu; picking one switches the color source to Custom colors.", "Fuente, tamaños de texto y opacidad del fondo. Los colores del rastreador están en el menú de tres puntos de esta sección; elegir uno cambia el origen del color a Colores personalizados.")
T("Fonts", "Fuentes")
T("Fonts, outlines, shadows and Smooth/Sharp/Slug rendering for keybinds, macro names, counts and cooldown numbers. Sizes are set per bar below. Slug has no shadow.", "Fuentes, contornos, sombras y renderizado Suave/Nítido/Slug para teclas, nombres de macros, contadores y números de reutilización. Los tamaños se definen por barra abajo. Slug no tiene sombra.")
