T("For Warlocks: show Burning Rush only while its aura is active in combat. Blizzard's native aura container follows the aura; Suite does not scan auras. MSUF Edit Mode shows a sample and moves the cue.", "Para brujos: muestra Ímpetu ardiente solo mientras su aura esté activa en combate. El contenedor de auras original de Blizzard sigue el aura; Suite no analiza las auras. El modo de edición de MSUF muestra una vista previa y mueve el aviso.")
T("Forces", "Fuerzas")
T("Forever Suite layout with Antique Map and optional parchment Skin.", "Distribución de Suite Forever con Antique Map y Skin de pergamino opcional.")
T("Forever artwork", "Diseño de Forever")
T("Forever factory profile unavailable", "Perfil de fábrica de Forever no disponible")
T("Forever only. A secure fishing key that casts Fishing, equipping the rod you choose first, and a second key that applies the lure you choose. Set both under Keybindings > MSUF Suite. Each action needs your key press; interacting with the bobber stays manual. The optional sound profile sets your fishing volumes while you cast and restores them afterwards.", "Solo en Forever. Una tecla de pesca segura equipa primero la caña elegida y lanza Pesca; una segunda tecla aplica el cebo elegido. Asigna ambas en Asignación de teclas > MSUF Suite. Cada acción necesita que pulses la tecla; interactuar con el flotador sigue siendo manual. El perfil de sonido opcional aplica los volúmenes de pesca al lanzar y los restaura después.")
T("Forever only. Route times are learned from completed flight-master journeys and kept in this profile. A first journey has no invented estimate. Early landing does not overwrite a full-route time. Intermediate stops come from the native taxi map; its tooltip can preview the route. Land at next stop requests the next available landing point.", "Solo Forever. Aprende tiempos de viajes completos y los guarda en este perfil. El primer viaje no tiene una estimación inventada. Aterrizar antes no sobrescribe el tiempo completo. Las paradas proceden del mapa nativo de vuelo, cuya ayuda puede mostrar la ruta. «Aterrizar en la siguiente parada» solicita el siguiente punto disponible.")
T("Forever only. When a quest offers a choice of rewards, the one with the highest vendor value, counting its stack size, is marked. Nothing is selected or turned in for you.", "Solo en Forever. Si una misión permite elegir recompensa, marca la de mayor valor de venta contando el tamaño de la pila. No selecciona ni entrega nada por ti.")
