T("Frames join aligned bars; detached bars keep separate frames. Effects are static. Threshold marks a fixed percentage. Preview switches apply live.", "El marco exterior une las barras de salud y lanzamiento; sin lanzamiento visible, rodea solo la salud. La sombra y el brillo son estáticos. Las texturas conservan los colores de salud y auras. La línea señala un porcentaje fijo, no una alerta de ejecución. Activa o desactiva cada función en Capas de vista previa. Las barras separadas o de distinto tamaño mantienen marcos independientes.")
