T("Friendly player display chooses Blizzard's setting, names for all friendly players, names for party / raid only, or health bars. Names only hides Blizzard bars, casts and auras for friendly players; it does not change NPC or enemy plates. Group / outsider in the preview only changes the sample. Blizzard can forbid changes to friendly plates in instances; those frames stay under Blizzard's control.", "Vista de jugadores amistosos elige el ajuste de Blizzard, nombres para todos los jugadores amistosos, nombres solo para grupo / banda, o barras de salud. Solo nombres oculta las barras, los lanzamientos y las auras de Blizzard de los jugadores amistosos; no cambia las placas de PNJ ni las enemigas. Grupo / externo en la vista previa solo cambia la muestra. Blizzard puede prohibir cambios en las placas amistosas dentro de instancias; esos marcos quedan bajo el control de Blizzard.")
