T("Gives Blizzard's player buffs and debuffs the icon skins you chose on the Icon Skins page, at Blizzard's own size and layout. The skins are painted once, out of combat, and no code runs on aura updates. While Player aura layout is on, it paints the buttons itself and this switch waits.", "Aplica a los beneficios y perjuicios del jugador de Blizzard los aspectos elegidos en Aspectos de iconos, manteniendo el tamaño y la disposición de Blizzard. Los aspectos se aplican una vez fuera de combate y no ejecutan código al actualizar auras. Mientras Disposición de auras del jugador esté activada, esa función dibuja los botones y este ajuste espera.")
T("Gives this bar's place, attachment, growth, rows and sizes to your other specializations. You can undo it.", "Aplica la posición, anclaje, crecimiento, filas y tamaños de esta barra a otras especializaciones. Puedes deshacerlo.")
