T("Hold Alt to see the ID of an item, spell, creature, quest, currency or temporary weapon enchant on its tooltip, or press Alt while the tooltip is open; the IDs stay until the tooltip is built again. Spell icon IDs and Blizzard's account character currency data are optional, and that data joins an open tooltip when it arrives. No ID or quantity appears when the client keeps it private.", "Mantén Alt para ver el ID de un objeto, hechizo, criatura, misión, moneda o encantamiento temporal de arma en su descripción, o presiona Alt con la descripción abierta; los ID se quedan hasta que la descripción se vuelve a construir. Los ID de íconos de hechizo y los datos de moneda de tus otros personajes de Blizzard son opcionales, y esos datos se agregan a una descripción abierta cuando llegan. No aparece ningún ID ni cantidad cuando el cliente los mantiene privados.")
T("Hold Alt to show item, spell, creature, quest, currency and temporary weapon enchant IDs on the main tooltip.", "Mantén Alt pulsado para ver en la descripción emergente principal los ID de objetos, hechizos, criaturas, misiones, monedas y encantamientos temporales de arma.")
T("Hold Midnight Artisan payouts while Shard of Dundun is capped", "Retener los pagos de artesano de Midnight al alcanzar el límite de Fragmentos de Dundun")
T("Hold Shift to pause. Quests with a money cost and quests with a reward choice always stay manual.", "Mantén Mayús para pausar. Las misiones con costo en dinero y las misiones con elección de recompensa siempre siguen siendo manuales.")
T("Hold a key to show hidden tooltips", "Mantener una tecla para mostrar descripciones ocultas")
T("Hold the selected key while clicking Release Spirit. The release button stays hidden until you hold it; resurrection and death recap remain available. Choose where to use the protection. Blizzard's automatic release timer is unchanged.", "Mantén pulsada la tecla elegida al hacer clic en Liberar espíritu. El botón permanece oculto hasta que la mantengas pulsada; la resurrección y el resumen de muerte siguen disponibles. Elige dónde aplicar la protección. El temporizador de liberación automática de Blizzard no cambia.")
T("Hold to release", "Mantener pulsado para liberar")
