T("Inside a raid the tracker turns into an encounter view at its usual place: boss name, pull timer, the bosses engaged right now with their health, your best wipe and your fastest kill. Phases come from DBM or BigWigs when one is installed; otherwise the phase stays open. A wipe with more bosses down beats one with fewer, and with the same count the one with less boss health left wins. Each character keeps its own records. Boss health shows only while the client reveals it.", "Dentro de una banda, el rastreador se convierte en su lugar habitual en una vista del encuentro: nombre del jefe, temporizador del intento, los jefes en combate con su salud, tu mejor intento fallido y tu victoria más rápida. Las fases llegan de DBM o BigWigs si hay uno instalado; si no, la fase queda abierta. Un intento con más jefes derrotados supera a uno con menos y, con el mismo número, gana el que deja menos salud a los jefes. Cada personaje guarda sus propios registros. La salud de los jefes solo aparece mientras el cliente la muestra.")
