T("Item tooltips take the color of the item quality, unit tooltips the class color of a player or the reaction color of any other unit. Keep leaves the border as it is. The Suite skin's tooltip border takes the color too.", "Las descripciones de objetos usan el color de su calidad; las de unidades, el color de clase del jugador o el de reacción de otras unidades. Mantener deja el borde sin cambios. El borde de las descripciones del aspecto de la Suite también recibe el color.")
