T("Items you protect are skipped by every sale action of the Suite. With the equipment set switch on, all equippable items are protected while any equipment set exists, because exact set membership is not available to this helper. Manage the protected items in the inventory tool.", "Los objetos protegidos se omiten en todas las ventas de la Suite. Con la protección de conjuntos activada, todos los objetos equipables quedan protegidos si existe algún conjunto, porque esta herramienta no puede conocer su pertenencia exacta. Gestiona los objetos protegidos en la herramienta de inventario.")
