T("Keep Blizzard grid, or choose one Suite grid, physical bag groups or categories. Use Edit categories in the bag window to create, rename, reorder or disable your categories; drop items onto a sidebar category to assign them. Sort items by orders every Suite view; Name keeps the order each view has always had. Click a category header to hide or show its items. The footer counts free slots, and Mark items that beat what you wear puts a small arrow on equipment that beats what you wear in its slot. Scroll or use Previous and Next for larger inventories; in combat every slot is shown at once. Combined stack counts are visual only; physical stacks are always restored at the bank, guild bank, mail, trade, auction house and merchant.", "Conserva la cuadrícula de Blizzard o elige una cuadrícula de la Suite, grupos de bolsas físicas o categorías. Usa Editar categorías en la ventana de bolsas para crearlas, renombrarlas, reordenarlas o desactivarlas; arrastra objetos a una categoría de la barra lateral para asignarlos. Ordenar objetos por ordena todas las vistas de la Suite; Nombre conserva su orden habitual. Pulsa el encabezado de una categoría para ocultar o mostrar sus objetos. El pie cuenta los espacios libres y Marcar objetos mejores que tu equipo añade una flecha al equipo que mejora lo que llevas en esa casilla. Desplázate o usa Anterior y Siguiente para inventarios grandes; en combate se muestran todas las casillas a la vez. Los recuentos combinados de pilas son solo visuales; las pilas físicas se restauran siempre en banco, banco de hermandad, correo, comercio, subasta y vendedor.")
