T("Limit the whole highlight to combat, to instances or to the open world, then give the pointer ring, the global cooldown and the cast fill their own combat rule. Nothing follows the pointer while it is hidden.", "Limita todo el resaltado al combate, a las estancias o al mundo abierto y luego da al anillo del puntero, al tiempo de reutilización global y al relleno del lanzamiento su propia regla de combate. Nada sigue al puntero mientras está oculto.")
