T("Lists carried gem types beside Blizzard's socket window. Inspect each gem with its normal bag tooltip and confirm compatibility in the native socket window before applying it.", "Muestra los tipos de gemas que llevas junto a la ventana de engarce de Blizzard. Inspecciona cada gema con la descripción normal de la bolsa y confirma su compatibilidad en la ventana original antes de aplicarla.")
T("Lists the casts of attackable enemy nameplates while you are in a five-player dungeon, oldest first; the game runs each bar and timer. The game keeps spell, target, marker and interrupt details hidden from addons, so casts are never sorted or filtered by them: fading or hiding uses the game's important-spell flag (a hidden cast keeps its place in the list), raid markers sit on the spell icon, and the ready mark, an edge stripe or the whole bar, shows on interruptible casts while your interrupt is off cooldown. Dimming checks four times a second whether your interrupt reaches each listed enemy; a cast it cannot check stays bright. The interrupt is found from your talents and pet unless you enter a spell ID. MSUF Edit Mode shows sample casts for placing the list.", "Muestra los lanzamientos de los enemigos atacables con placa de nombre mientras estás en un calabozo de cinco jugadores, del más antiguo al más reciente; el juego lleva cada barra y temporizador. El juego oculta a los addons el hechizo, el objetivo, la marca y si se puede interrumpir, así que los lanzamientos nunca se ordenan ni se filtran por ello: atenuar u ocultar usa la marca de hechizo importante del juego (un lanzamiento oculto conserva su lugar en la lista), las marcas de banda aparecen en el ícono del hechizo y la marca de lista, una franja en el borde o toda la barra, aparece en los lanzamientos interrumpibles mientras tu interrupción no está en tiempo de reutilización. La atenuación por alcance comprueba cuatro veces por segundo si tu interrupción llega a cada enemigo listado; un lanzamiento que no se puede comprobar sigue brillante. La interrupción se detecta por tus talentos y tu mascota salvo que indiques un ID de hechizo. El modo de edición de MSUF muestra lanzamientos de ejemplo para colocar la lista.")
T("Lists the casts of enemy nameplates in five-player dungeons, oldest first, with timers the game runs.", "Muestra los lanzamientos de las placas de nombre enemigas en calabozos de cinco jugadores, del más antiguo al más reciente, con temporizadores que lleva el juego.")
