T("MSUF stops only a log it started. A log that was already on stays on. Re-entering selected content cancels a pending stop. WoW writes the log in its Logs folder.", "MSUF solo detiene un registro que inició. Un registro que ya estaba activo sigue activo. Volver a entrar al contenido elegido cancela una detención pendiente. WoW escribe el registro en su carpeta Logs.")
