T("Mapko uses Modern plates, Medium size and the same bar dimensions on Retail and Forever. Guild names and titles also affect names in the world. Bind Toggle friendly NPC nameplates under MSUF Suite in Blizzard Key Bindings. Import protection keeps your current nameplates when importing a full Suite profile; explicit nameplate imports still replace them.", "Mapko usa placas modernas, tamaño mediano y las mismas dimensiones de barra en Retail y Forever. Los nombres de hermandad y títulos también afectan a los nombres del mundo. Asigna Alternar placas de PNJ amistosos en MSUF Suite, dentro de las teclas de Blizzard. La protección de importación conserva tus placas al importar un perfil completo de Suite; las importaciones específicas de placas sí las reemplazan.")
