T("Observed enemies adds up the enemy forces of the living enemies in combat that you see as a nameplate or target, and the total they would bring. Enemies that give no forces count as zero; while the client keeps a value hidden, the line shows -- instead of a guess. Enemies out of sight are not counted.", "Enemigos observados suma las fuerzas enemigas de los enemigos vivos en combate que ves como placa de nombre u objetivo, y el total que aportarían. Los enemigos que no dan fuerzas cuentan como cero; mientras el cliente oculta un valor, la línea muestra -- en lugar de una estimación. Los enemigos fuera de la vista no se cuentan.")
