T("Open Blizzard's raid tools, start a pull countdown, or mark one party tank or healer by command or opt-in automation.", "Abre las herramientas de banda de Blizzard, inicia una cuenta atrás o marca al tanque o sanador del grupo con un comando o una opción automática voluntaria.")
T("Open Colors", "Abrir Colores")
