T("Open newly acquired loot containers one at a time outside combat. Hold Shift to leave them manual.", "Abre los contenedores de botín recién adquiridos uno a la vez fuera del combate. Mantenga presionada la tecla Mayús para dejarlos manuales.")
T("Open notice history", "Abrir historial de avisos")
T("Open or show the module before moving it.", "Abre o muestra el módulo antes de moverlo.")
T("Open related settings", "Abrir ajustes relacionados")
