T("Open the MSUF menu to find the Suite pages. MSUF must be installed and enabled.", "Abre el menú de MSUF para encontrar las páginas de Suite. MSUF debe estar instalado y activado.")
T("Open the map after setting a waypoint", "Abrir el mapa después de establecer un punto de ruta")
T("Open the window to see everyone.", "Abre la ventana para ver a todos.")
T("Open this page out of combat to load the cooldown manager.", "Abre esta página fuera de combate para cargar el gestor de reutilización.")
T("Open world", "Mundo abierto")
T("Open your bank and select its destination tab type. Search the preview, select a stack, then click Move stack.", "Abre el banco y elige el tipo de pestaña de destino. Busca en la vista previa, selecciona una pila y pulsa Mover pila.")
T("Open your equipment window beside an item upgrade merchant and close only the window MSUF opened.", "Abre tu ventana de equipo junto al vendedor de mejoras de objetos y cierra solo la ventana que abrió MSUF.")
T("Opens your character window, on the tab you used last, when an item upgrade merchant opens. It closes only a window this helper opened and waits for the end of combat to open or close it.", "Abre tu ventana de personaje, en la última pestaña que usaste, al abrir un vendedor de mejoras de objetos. Cierra solo una ventana abierta por este asistente y espera al final del combate para abrirla o cerrarla.")
T("Optional Blizzard settings for chat, map, sound and low-health or alternate screen flashes. MSUF restores the previous value when you turn a choice or this helper off. Changes you make yourself in Blizzard settings while this helper runs are respected.", "Ajustes opcionales de Blizzard para el chat, el mapa, el sonido y los destellos de pantalla por salud baja o alternativos. MSUF restaura el valor anterior al desactivar una opción o el asistente. Los cambios que hagas por tu cuenta en los ajustes de Blizzard mientras funciona el asistente se respetan.")
T("Optional artwork and spacing controls. Use MSUF Edit Mode for position, nudging, reset, undo and redo.", "Controles opcionales de arte y espaciado. Usa el modo de edición de MSUF para la posición, los ajustes finos, restablecer, deshacer y rehacer.")
T("Optional shortcuts for tutorials, item deletion and screenshot notices.", "Atajos opcionales para tutoriales, borrado de objetos y avisos de capturas de pantalla.")
