T("Remember characters visited with this helper enabled.\nClick a recipient to fill the address; right-click to hide or restore it.", "Recuerda los personajes visitados con esta ayuda activada.\nHaz clic para rellenar la dirección; clic derecho para ocultar o restaurar al destinatario.")
