T("Remembers your characters that you visit while this helper is on and lists them beside the mail window. Click a name to fill the recipient, right-click to hide or restore it, and search by name. Only characters on your current or connected realms are listed. Sending stays manual.", "Recuerda los personajes que visitas mientras esta herramienta está activa y los muestra junto a la ventana de correo. Pulsa un nombre para rellenar el destinatario, haz clic derecho para ocultarlo o restaurarlo y busca por nombre. Solo aparecen personajes de tu reino actual o de reinos conectados. El envío sigue siendo manual.")
