T("Reminders appear only outside combat. The advance setting also shows active buffs, food and weapon enchants when their remaining time reaches the chosen number of minutes; 0 shows only missing effects. A single scheduled wakeup handles the next threshold. Reminders hide in arenas and battlegrounds, where aura data can be restricted.", "Los recordatorios solo aparecen fuera de combate. El ajuste de anticipación también muestra beneficios activos, comida y encantamientos de arma cuando su tiempo restante llega al número de minutos elegido; 0 muestra solo los efectos faltantes. Una única activación programada gestiona el siguiente umbral. Los recordatorios se ocultan en arenas y campos de batalla, donde los datos de auras pueden estar restringidos.")
T("Reminders for missing poisons and consumables.", "Avisos de venenos y consumibles que faltan.")
T("Reminders for the buffs your class and specialization keep up.", "Recordatorios de los beneficios que mantienen tu clase y especialización.")
