T("Repair equipment and sell poor-quality items when a merchant opens. Hold Shift to skip selling.", "Repara el equipo y vende los objetos de calidad pobre al abrir un comerciante. Mantén Mayús para omitir la venta.")
T("Repairs only when the cost is within your limit. Guild funds are used first when allowed.", "Solo repara cuando el costo está dentro de tu límite. Los fondos de la hermandad se usan primero cuando está permitido.")
T("Replace Blizzard event banners", "Reemplazar carteles de eventos de Blizzard")
T("Replace objectives with the Mythic+ timer during a key", "Reemplazar objetivos con el temporizador de Mítica+ durante una llave")
T("Replace the linked WoW macro?", "¿Reemplazar la macro de WoW vinculada?")
T("Replaces the merchant's pages with one list; scroll it with the mouse wheel or the bar. Right-click buys, left-click picks an item up and Shift-click asks for a quantity; linking and previewing work as usual. Purchases paid with currencies or items, or costing at least 150 gold, ask for confirmation first. The buyback tab keeps Blizzard's layout. Drop or click an item from your bags onto the list to sell it; one you can still refund asks whether to refund it.", "Reemplaza las páginas del comerciante con una sola lista; desplázala con la rueda del mouse o la barra. Clic derecho compra, clic izquierdo toma un objeto y Mayús-clic pide una cantidad; vincular y previsualizar funcionan como siempre. Las compras pagadas con monedas u objetos, o que cuestan al menos 150 de oro, piden confirmación primero. La pestaña de recompra conserva el diseño de Blizzard. Suelta o haz clic con un objeto de tus bolsas sobre la lista para venderlo; si aún puede reembolsarse, pregunta si quieres reembolsarlo.")
T("Report", "Informe")
T("Report in a window's Settings menu sends its ranking to chat once combat is over.", "Informe, en el menú de ajustes de una ventana, envía su clasificación al chat cuando termina el combate.")
T("Report junk sale requests in chat", "Informar en el chat las solicitudes de venta de basura")
T("Report updated action slots", "Informar de las casillas actualizadas")
T("Reports group member deaths in chat during combat.", "Informa en el chat de las muertes de miembros del grupo durante el combate.")
T("Reports the first observed death of each group member during combat. Local chat, a screen notice and a sound can be selected separately. Simultaneous deaths share one sound. Optionally include your own death. The listener is active only while you are grouped and in combat.", "Avisa de la primera muerte observada de cada miembro del grupo durante el combate. Puedes elegir por separado el chat local, el aviso en pantalla y el sonido. Las muertes simultáneas comparten un sonido. Puedes incluir tu propia muerte. Solo se escucha mientras estás en grupo y en combate.")
T("Reputation", "Reputación")
