T("Requires Center alignment. Icons alternate around the first icon. Buffs keep fixed places; inactive buffs leave gaps.", "Con la alineación Centro, el primer icono permanece en el centro y los siguientes alternan los lados. Los iconos de beneficios conservan posiciones fijas; los beneficios inactivos dejan huecos.")
