T("Restores this bar's default spells and buffs for your specialization. Other bars and specializations stay as they are. You can undo it.", "Restaura los hechizos y beneficios predeterminados de esta barra para tu especialización. Las demás barras y especializaciones se mantienen como están. Puedes deshacerlo.")
T("Restyles Blizzard's own buff and debuff buttons beside the minimap: icon size, icons per row, spacing, outline, text and where the block sits. Blizzard still owns the auras, their tooltips and right-click cancelling. The position and the debuff row offset are set here, not in Edit Mode. Each row's icon skin is chosen on the Icon Skins page.", "Modifica los botones de beneficios y perjuicios de Blizzard junto al minimapa: tamaño, iconos por fila, separación, contorno, texto y posición del bloque. Blizzard conserva el control de las auras, sus descripciones y su cancelación con clic derecho. La posición y el desplazamiento de la fila de perjuicios se ajustan aquí, no en el modo de edición. El aspecto de iconos de cada fila se elige en Aspectos de iconos.")
T("Result", "Resultado")
T("Results and details", "Resultados y detalles")
T("Resurrection offers", "Ofertas de resurrección")
T("Retail Druids only. Every incoming whisper in combat is a possible Innervate cue; message text cannot be inspected reliably during chat lockdown. The alert waits for a publicly known Innervate cooldown, or shows a generic cue when readiness is unavailable. A preferred target can be outlined on an MSUF group frame resolved outside combat. MSUF Edit Mode previews the alert and edits its position and size.", "Solo druidas en Retail. Cada susurro entrante en combate es un posible aviso de Estimular; el texto del mensaje no se puede inspeccionar de forma fiable durante el bloqueo del chat. La alerta espera a un tiempo de reutilización de Estimular conocido públicamente, o muestra un aviso genérico cuando no se sabe si está listo. Se puede resaltar con un contorno a un objetivo preferido en un marco de grupo de MSUF resuelto fuera de combate. El modo de edición de MSUF muestra una vista previa de la alerta y edita su posición y tamaño.")
T("Retail only. Shows while Skyriding is available, or only in flight if selected. Choose bars or Blizzard Vigor gems; gem scale and a refill sound are optional. Separate bar heights, Surge icon size and speed-value offsets are under Text and bars. MSUF Edit Mode previews the HUD. Unknown charge values display as dashes.", "Solo Retail. Se muestra mientras vuelo dinámico está disponible o, si se elige, solo en vuelo. Selecciona barras o gemas de vigor de Blizzard; escala y sonido de recarga son opcionales. Alturas separadas, tamaño del icono de impulso y desplazamientos de velocidad están en Texto y barras. El modo de edición MSUF muestra una vista previa. Cargas desconocidas aparecen como guiones.")
T("Return to current fight", "Volver al combate actual")
T("Return to the current fight when combat starts", "Volver al combate actual cuando empieza el combate")
T("Return to the saved builder rules? Custom code stays in the Code tab.", "¿Volver a las reglas guardadas del constructor? El código personalizado permanece en la pestaña Código.")
T("Returns this specialization to its short raid essentials list. Your other bars and specializations stay as they are. You can undo it.", "Devuelve esta especialización a su lista corta de esenciales de banda. Tus demás barras y especializaciones se mantienen como están. Puedes deshacerlo.")
T("Reveal the chat with", "Mostrar el chat con")
