T("Show weather as text, an icon, or both. Choose Blizzard icons or original Forever artwork. The tooltip keeps the weather name when only the icon is shown.", "Muestra el clima como texto, un icono o ambos. Elige iconos de Blizzard o diseños originales de Forever. La descripción emergente conserva el nombre del clima cuando solo se muestra el icono.")
T("Show weekly reward item levels", "Mostrar niveles de objeto de recompensas semanales")
