T("Show windows", "Mostrar ventanas")
T("Show your Bloodlust exhaustion or ready state while grouped.", "Muestra si tienes Agotamiento tras Ansia de sangre o si estás listo mientras estás en grupo.")
T("Show your owned item count, including bank and Warband bank, on item tooltips.", "Muestra en las descripciones de los objetos cuántos posees, incluidos el banco y el banco de banda guerrera.")
T("Show your selected loot specialization in the Great Vault window.", "Muestra tu especialización de botín elegida en la ventana de la Gran Cámara.")
T("Show zone", "Mostrar zona")
T("Show, hide and customize Blizzard's player buff and debuff bars.", "Muestra, oculta y personaliza las barras de beneficios y perjuicios del jugador de Blizzard.")
T("Shown value", "Valor mostrado")
T("Shown windows: %d. Raise the number of windows to show this one.", "Ventanas mostradas: %d. Aumenta el número de ventanas para mostrar esta.")
T("Shows Blizzard's shared battle resurrection charges in an active Mythic+ run or raid encounter. The icon counts down to the next charge using Blizzard's cooldown display. Hidden when the shared pool is unavailable. MSUF Edit Mode previews the display and edits X, Y, width, height and scale.", "Muestra las cargas compartidas de resurrección en combate de Blizzard en una Mítica+ activa o en un encuentro de banda. El icono cuenta hasta la siguiente carga con la visualización de reutilización de Blizzard. Oculto cuando la reserva compartida no está disponible. El modo de edición de MSUF muestra una vista previa y edita X, Y, ancho, altura y escala.")
T("Shows an approximate range to your current target from the game's range checks of spells you know; values include the target's hitbox, and dashes mean that no known spell can tell. Write the text with {range} and {unit}. The estimate can sit below the target frame, following it when the frame moves, or anywhere on screen; MSUF Edit Mode moves both placements.", "Muestra una distancia aproximada a tu objetivo actual a partir de las comprobaciones de alcance del juego para los hechizos que conoces; los valores incluyen la zona de impacto del objetivo y los guiones indican que ningún hechizo conocido puede determinarla. Escribe el texto con {range} y {unit}. La estimación puede ir debajo del marco de objetivo, siguiéndolo cuando el marco se mueve, o en cualquier lugar de la pantalla; el modo de edición de MSUF mueve ambas ubicaciones.")
T("Shows each ready interrupt with the bar's glow style while the target's cast can be interrupted. Requires per-interrupt readiness from MSUF.", "Muestra cada interrupción disponible con el estilo de brillo de la barra mientras se pueda interrumpir el lanzamiento del objetivo. Requiere datos de disponibilidad de cada interrupción de MSUF.")
T("Shows incoming damage and healing for you or your vehicle. Blizzard's own combat text is hidden while enabled and restored when disabled. Move the display in MSUF Edit Mode. During heavy bursts the oldest of the visible messages is replaced. The game may keep amounts private, so messages are never combined or filtered by their value.", "Muestra el daño y la sanación que recibes tú o tu vehículo. El texto de combate de Blizzard se oculta mientras está activado y se restaura al desactivarlo. Mueve la visualización en el modo de edición de MSUF. Cuando hay muchos mensajes, se reemplaza el más antiguo visible. El juego puede ocultar los valores; nunca se suman ni se filtran por su cantidad.")
T("Shows item levels on merchant equipment when Blizzard has loaded its item data. Buyback items and items without an item level stay unchanged.", "Muestra los niveles de objeto en el equipo de los comerciantes cuando Blizzard ha cargado sus datos de objeto. Los objetos de recompra y los objetos sin nivel de objeto no cambian.")
T("Shows the active potion buff. Instant healing and mana potions do not leave a buff.", "Muestra el beneficio activo de la poción. Las pociones de salud y maná instantáneas no dejan un beneficio.")
T("Shows the current loot specialization when you open the Great Vault. Updates if you change loot specialization while the window is open.", "Muestra la especialización de botín actual al abrir la Gran Cámara. Se actualiza si cambias la especialización de botín con la ventana abierta.")
T("Shows the lowest equipped durability below your chosen threshold, outside combat. MSUF Edit Mode shows a sample even when your gear is repaired. Its popup edits X, Y, width, height and scale.", "Muestra la durabilidad equipada más baja por debajo del umbral elegido, fuera de combate. El modo de edición de MSUF muestra un ejemplo aunque tu equipo esté reparado. Su ventana emergente edita X, Y, ancho, altura y escala.")
T("Shows the number you own, including your bank and Warband bank, when the item tooltip has a public item ID. Optionally separate storage locations. Empty counts are omitted.", "Muestra cuántos objetos posees, incluidos los del banco y el banco de banda guerrera, si la descripción contiene un ID público de objeto. Puedes mostrar cada almacén por separado. Se omiten las cantidades vacías.")
T("Shows the share of the keystone's enemy forces that an enemy gives, while a Mythic+ keystone is running and Blizzard shows no such line itself.", "Muestra la proporción de fuerzas enemigas que aporta un enemigo durante una piedra angular de Mítica+ si Blizzard no muestra ya esa línea.")
T("Shows the spell's icon in the middle of the screen when its cooldown ends, even while this bar is hidden. Its size, place and time are in General.", "Muestra el icono del hechizo en el centro de la pantalla cuando termina su reutilización, aunque esta barra esté oculta. El tamaño, la posición y la duración están en General.")
T("Shows the total durability of your gear on the character model, moved by the two offsets, and crops the edges of the gear slot icons on your character sheet and in the Inspect window.", "Muestra la durabilidad total de tu equipo sobre el modelo del personaje, movida por los dos desplazamientos, y recorta los bordes de los íconos de ranura en tu hoja de personaje y en la ventana de inspección.")
T("Shows up to three extra compact notices for Blizzard personal item-loot toasts. Filter by minimum quality, mount or pet items, and optionally up to 100 item IDs. Native Blizzard notices remain visible; ordinary bag additions without a toast are not included.", "Muestra hasta tres avisos compactos adicionales de botín personal de Blizzard. Filtra por calidad mínima, objetos de montura o mascota y, opcionalmente, hasta 100 ID de objeto. Los avisos originales de Blizzard siguen visibles; no se incluyen los objetos añadidos normalmente a las bolsas sin aviso.")
T("Shows whichever haste buff is active, from any source: Bloodlust, Heroism, Time Warp, Primal Rage, Fury of the Aspects and similar.", "Muestra el beneficio de celeridad activo, sea cual sea su origen: Ansia de sangre, Heroísmo, Distorsión temporal, Rabia primigenia, Furia de los Aspectos y otros similares.")
T("Shows your current talent build and loot specialization on ready checks, when a dungeon queue pops, or when you enter an instance. It never changes your talents or loot spec.", "Muestra tu configuración de talentos y especialización de botín actuales al comprobar si el grupo está listo, al aparecer una cola de calabozo o al entrar en una instancia. Nunca cambia tus talentos ni la especialización de botín.")
T("Shows your most recent successful spells. Standard rows have an icon, name and marker; Icons only is a compact vertical icon column. Display width applies to standard rows; icon width follows row height in the icon preset. Position and anchor are set in MSUF Edit Mode, which shows sample actions. The list stops listening while disabled. Spells whose details the client keeps private cannot appear.", "Muestra tus últimos hechizos lanzados con éxito. Las filas estándar incluyen icono, nombre y marcador; «Solo iconos» es una columna vertical compacta. La anchura de visualización se aplica a las filas estándar; en «Solo iconos», la anchura depende de la altura de fila. La posición y el anclaje se ajustan en el modo de edición de MSUF, que muestra acciones de ejemplo. La lista deja de escuchar eventos al desactivarse. Los hechizos cuyos datos el cliente mantiene privados no pueden mostrarse.")
T("Shows your own Bloodlust exhaustion while in a group, or a ready state if you prefer. Relevant player aura changes update it; MSUF Edit Mode moves it and previews the locked state.", "Muestra tu Agotamiento tras Ansia de sangre mientras estás en grupo, o el estado «Listo» si lo prefieres. Los cambios relevantes en tus auras lo actualizan. El modo de edición de MSUF permite moverlo y previsualizar el estado de agotamiento.")
