T("Silences the game sound files whose IDs you list, such as a mount or summon sound; up to 200. MSUF mutes exactly the files listed here and plays them again when you remove an ID or turn this helper off, and it leaves files muted by other addons alone. Muting works whether or not volume profiles are applied.", "Silencia los archivos de sonido del juego cuyos ID indiques, como sonidos de monturas o invocaciones; hasta 200. MSUF silencia exactamente los archivos de esta lista y los restaura al eliminar un ID o desactivar la herramienta. No altera archivos silenciados por otros addons. Funciona con o sin perfiles de volumen activos.")
T("Silences these game sound files, such as a mount or summon sound, while this helper is on. Remove an ID to hear that sound again.", "Silencia estos archivos de sonido del juego, como sonidos de monturas o invocaciones, mientras la herramienta está activa. Elimina un ID para volver a oír ese sonido.")
