T("Skin only Blizzard's own personal mana and alternate-power status bars. Blizzard still owns their values, fill and visibility. Class-specific resource points retain Blizzard's layout. Select and drag the power bar in the personal preview.", "Aplica skin solo a las barras de estado de maná personal y de poder alternativo propias de Blizzard. Blizzard sigue controlando sus valores, su relleno y su visibilidad. Los puntos de recurso específicos de clase conservan el diseño de Blizzard. Selecciona y arrastra la barra de recurso en la vista previa personal.")
