T("Switch between native tabs, combined bank, combined warbank and shared categories with the button below the bank window. Shared categories include accessible character and warbank tabs. Manage bank tabs returns to Blizzard purchases, deposits and tab settings. The bank views have the same smart search, free slot count and collapsible category headers. Every slot keeps its own item action and bank stacks are never merged; clicking a warband item selects Blizzard's Warband Bank tab first, and a refundable item asks before it enters the warband bank.", "Usa el botón bajo la ventana del banco para alternar entre pestañas nativas, banco combinado, banco de banda guerrera combinado y categorías compartidas. Estas categorías incluyen pestañas accesibles del personaje y de la banda guerrera. Gestionar pestañas del banco vuelve a las compras, depósitos y ajustes de Blizzard. Las vistas del banco tienen la misma búsqueda inteligente, contador de espacios libres y encabezados plegables. Cada casilla conserva su propia acción y las pilas del banco nunca se combinan; pulsar un objeto de la banda guerrera selecciona primero la pestaña de Banco de la banda guerrera de Blizzard y un objeto reembolsable pide confirmación antes de entrar en ella.")
T("Switch each bar on or off here. Turning it back on restores its previous visibility mode. Select Layout to customize the bar selected above.", "Activa o desactiva cada barra aquí. Al activarla se restaura su modo de visibilidad anterior. Selecciona Diseño para personalizar la barra elegida arriba.")
T("Switch on the first option, then keep or drop the reminders you want. A reminder shows only when your character knows its spell. Stances, auras, shields, Shadowform and weapon or shield imbues show while they are missing. Buffs you put on an ally (Source of Magic, Blistering Scales, Earth Shield, Symbiotic Relationship) show while your buff is on nobody in the group; target an ally and click the icon to cast it. Right-click or middle-click any reminder to hide it until you reload the UI.", "Activa la primera opción y después conserva o desactiva los recordatorios que quieras. Un recordatorio solo aparece si tu personaje conoce el hechizo. Las actitudes, auras, escudos, Forma de las Sombras y mejoras de arma o escudo aparecen cuando faltan. Los beneficios que aplicas a un aliado (Fuente de magia, Escamas virulentas, Escudo de tierra, Relación simbiótica) aparecen mientras nadie del grupo tenga tu beneficio; selecciona un aliado y pulsa el icono para lanzarlo. Haz clic derecho o central en cualquier recordatorio para ocultarlo hasta recargar la interfaz.")
T("Switch the whole Skinning module here, or adjust Blizzard and Suite windows separately below.", "Activa o desactiva aquí todo el módulo Skins, o ajusta por separado abajo las ventanas de Blizzard y de la Suite.")
