T("The Mapko skin for Blizzard nameplates. Blizzard keeps health, threat, casts, auras, selection and click handling.", "El aspecto Mapko para las placas de Blizzard. Blizzard mantiene el control de salud, amenaza, lanzamientos, auras, selección y clics.")
T("The Suite Cooldown manager page (CDM) shows Blizzard's tracked cooldowns and buffs as bars you arrange and style freely.", "La página Gestor de tiempos de reutilización (CDM) de Suite muestra los tiempos de reutilización y beneficios registrados por Blizzard como barras que puedes colocar y personalizar libremente.")
T("The Suite Minimap page styles the minimap itself: size, shape, border, zoom, buttons and info texts. MSUF's own minimap icon is under Miscellaneous.", "La página Minimapa de Suite personaliza el propio minimapa: tamaño, forma, borde, zoom, botones y textos informativos. El icono de minimapa de MSUF está en Miscelánea.")
T("The Suite Nameplates page styles Blizzard's enemy and friendly nameplates. MSUF's aura filters only decide whether nameplate-only auras show on MSUF frames.", "La página Placas de nombre de Suite personaliza las placas de nombre de enemigos y aliados de Blizzard. Los filtros de auras de MSUF solo determinan si las auras exclusivas de las placas de nombre se muestran en los marcos de MSUF.")
T("The Suite draws its own tracker and hides Blizzard's while it runs. Entries are sorted into groups: the focused quest, campaign and important quests, quests ready to hand in, regular quests, world quests, nearby bonus objectives, scenario and delve steps, zone event progress, tracked achievements and collectibles and, on Retail, tracked recipes, Traveler's Log activities and Housing endeavors. In a raid it can hide completely, only while a boss is engaged, or pause the regular list during any raid fight; the encounter view keeps running then. Quest symbols come as Suite letters or as Blizzard's icons, and the heading line can be switched off. The key binding Use tracked quest item uses the focused quest's item, else the first usable one, and picks a new item only outside combat. Left-click a group name to fold it or a quest to open its log entry; right-click for more actions.", "La Suite dibuja su propio seguimiento y oculta el de Blizzard mientras está activo. Agrupa la misión enfocada, campañas y misiones importantes, misiones listas para entregar, misiones normales, misiones del mundo, objetivos de bonificación cercanos, pasos de escenarios y profundidades, progreso de eventos de zona, logros y coleccionables seguidos y, en Retail, recetas seguidas, actividades del Diario de viaje e iniciativas de vivienda. En banda puede ocultarse por completo, solo durante un jefe, o pausar la lista normal durante cualquier combate de banda; la vista del encuentro sigue funcionando. Los símbolos de misión pueden ser letras de la Suite o iconos de Blizzard, y la cabecera se puede ocultar. La asignación Usar objeto de misión seguida usa el de la misión enfocada o, si no, el primer objeto utilizable, y solo elige uno nuevo fuera de combate. Pulsa un grupo para plegarlo o una misión para abrirla en el registro; haz clic derecho para ver más acciones.")
T("The Suite frames Blizzard's original Micro Buttons. Their artwork, clicks, tooltips, enabled states and notifications stay native. Queue and FPS indicators stay at Blizzard's Edit Mode position. No recurring MSKIN update runs.", "La Suite enmarca los botones originales del micromenú de Blizzard. Sus gráficos, clics, descripciones emergentes, estados de activación y notificaciones siguen siendo los originales. Los indicadores de cola y de FPS permanecen en su posición del modo de edición de Blizzard. No se ejecuta ninguna actualización periódica de MSKIN.")
T("The Suite look gives Blizzard's dialogs a dark panel, and the Suite font sets their text font and size; each works alone, and without them dialogs keep Blizzard's look and fonts. A minimum height makes short dialogs taller once Blizzard has sized them; 0 keeps Blizzard's height. A custom position moves the first dialog and the ones Blizzard stacks below it; place it and set the height in MSUF Edit Mode.", "El aspecto de la Suite da a los diálogos de Blizzard un panel oscuro y la fuente de la Suite fija la fuente y el tamaño de su texto; cada uno funciona por separado y, sin ellos, los diálogos conservan el aspecto y las fuentes de Blizzard. Una altura mínima alarga los diálogos cortos después de que Blizzard los dimensiona; 0 conserva la altura de Blizzard. Una posición propia mueve el primer diálogo y los que Blizzard apila debajo; colócalo y ajusta la altura en el modo de edición de MSUF.")
T("The Suite skin engine is unavailable.", "El motor de skins de la Suite no está disponible.")
T("The WoW macro changed; import it again before replacing it", "La macro de WoW ha cambiado; impórtala de nuevo antes de reemplazarla")
T("The WoW macro is no longer available", "La macro de WoW ya no está disponible")
T("The action-bar glow also requires this buff on you. Clear the field to use only the original buff or stack condition.", "El brillo de la barra de acción también requiere este beneficio sobre ti. Vacía el campo para usar solo el beneficio original o la condición de acumulaciones.")
T("The bank selection changed. Review the preview again.", "La selección del banco cambió. Revisa la vista previa otra vez.")
T("The chosen font could not be applied.", "No se ha podido aplicar la fuente elegida.")
T("The chosen font was not found, so Blizzard text keeps its own font.", "No se ha encontrado la fuente elegida; los textos de Blizzard conservan su fuente.")
T("The chosen profile supplies all settings. Toggle which Suite modules are enabled in it.", "El perfil elegido proporciona todos los ajustes. Elige qué módulos de la Suite están activados en él.")
T("The class buff is included only when your character knows it. Enter self-buff spell IDs separated by spaces or commas. For a consumable, enter item ID:aura ID; separate pairs with commas. Up to 12 total reminders are shown. Weapon enchant items use the main-hand or off-hand enchant state.", "El beneficio de clase solo se incluye cuando tu personaje lo conoce. Ingresa los ID de hechizo de beneficios propios separados por espacios o comas. Para un consumible, ingresa ID de objeto:ID de aura; separa los pares con comas. Se muestran hasta 12 recordatorios en total. Los objetos de encantamiento de arma usan el estado del encantamiento de mano principal o de mano secundaria.")
T("The combined bag and reagent bag use a Suite panel with a distinct header, border, and accent line. Set background opacity to 0 for a transparent window; item slots stay visible.", "La bolsa combinada y la bolsa de componentes usan un panel de la Suite con encabezado, borde y línea de acento propios. Pon la opacidad del fondo en 0 para una ventana transparente; las casillas de objetos siguen visibles.")
T("The combined bag setting is protected on this client", "El ajuste de bolsa combinada está protegido en este cliente")
T("The configuration cannot be opened during combat.", "La configuración no se puede abrir en combate.")
T("The cooldown catalog is not available yet. Log in on this character and specialization, then open this page.", "El catálogo de tiempos de reutilización aún no está disponible. Inicia sesión con este personaje y esta especialización y abre esta página.")
T("The cooldown manager is not loaded.", "El gestor de reutilización no está cargado.")
T("The cooldown manager needs an update. Reload the interface.", "El gestor de reutilización necesita una actualización. Recarga la interfaz.")
T("The cooldown manager was reset: settings, spell lists and spell options.", "Se restableció el gestor de reutilización: ajustes, listas de hechizos y opciones de hechizos.")
T("The countdown turns to the warning color below this many seconds. All bars: the Text section's setting.", "La cuenta regresiva cambia al color de advertencia por debajo de esta cantidad de segundos. Todas las barras: el ajuste de la sección Texto.")
T("The dark sweep over the icon while it counts down.", "El barrido oscuro sobre el icono mientras hace la cuenta regresiva.")
T("The default font follows MSUF Fonts while the default size follows Blizzard's chat size. Choose Blizzard chat font to keep its own face. Slug has no shadow.", "La fuente predeterminada sigue las Fuentes de MSUF, mientras que el tamaño predeterminado sigue el tamaño del chat de Blizzard. Elige Fuente de chat de Blizzard para mantener su propia tipografía. Slug no tiene sombra.")
T("The detailed character panel and stats are available only in Retail. WoW Forever keeps its own character layout.", "El panel de personaje detallado y las estadísticas solo están disponibles en Retail. WoW Forever conserva su propia disposición.")
T("The detailed character panel is available only in Retail.", "El panel de personaje detallado solo está disponible en Retail.")
T("The dungeon's timer", "El temporizador del calabozo")
T("The engine remains dormant until a lifecycle event or an explicit user action requires work.", "El motor permanece inactivo hasta que un evento del ciclo de vida o una acción explícita del usuario requiere trabajo.")
T("The game could not use the chosen font, so Blizzard text keeps its own font.", "El juego no ha podido usar la fuente elegida; los textos de Blizzard conservan su fuente.")
T("The game has not sent the current season yet; until then every learned portal is listed.", "El juego todavía no envía la temporada actual; mientras tanto se muestran todos los portales aprendidos.")
T("The global cooldown can leave the ring for a fixed circle of its own size and opacity, shown next to casts. Place it in MSUF Edit Mode; its button there works while this choice is on.", "El tiempo de reutilización global puede salir del anillo a un círculo fijo con su propio tamaño y opacidad, visible junto a los lanzamientos. Colócalo en el modo de edición de MSUF; su botón allí funciona mientras esta opción esté activa.")
T("The global name of a frame, for example ChatFrame1. The bar follows its place and size, never anchored to it. Until the frame exists, the bar stays put.", "El nombre global de un marco, por ejemplo ChatFrame1. La barra sigue su posición y tamaño sin anclarse directamente a él. Hasta que exista, la barra permanece en su sitio.")
T("The header shows the meter and fight. Its buttons change the meter and fight directly in the window.", "El encabezado muestra el medidor y el combate. Sus botones cambian el medidor y el combate directamente en la ventana.")
T("The item changed. Review the preview again.", "El objeto cambió. Revisa la vista previa otra vez.")
T("The keystone notice remains local. The optional group announcement forwards only Blizzard's confirmed reset message immediately after your own reset request, while you are group leader. Failed attempts and resets by other players are not announced.", "El aviso de piedra angular sigue siendo local. El anuncio opcional al grupo solo reenvía el mensaje de reinicio confirmado de Blizzard inmediatamente después de tu propia solicitud, mientras eres líder del grupo. No anuncia intentos fallidos ni reinicios de otros jugadores.")
T("The level number takes the color Blizzard gives it on the target frame. Units you cannot attack keep white.", "El número de nivel usa el color que Blizzard le asigna en el marco del objetivo. Las unidades a las que no puedes atacar permanecen en blanco.")
T("The list of kept buttons is full.", "La lista de botones conservados está llena.")
T("The macro draft is no longer available", "El borrador de macro ya no está disponible")
T("The macro exceeds the 255-character limit", "La macro supera el límite de 255 caracteres.")
T("The macro library is full", "La biblioteca de macros está llena")
T("The map grows or shrinks to the chosen width and height while the pointer is over it, then returns to its normal size. A circular map keeps its height equal to its width.", "El mapa crece o se reduce al ancho y la altura elegidos mientras el puntero está sobre él, y luego vuelve a su tamaño normal. Un mapa circular mantiene su altura igual a su ancho.")
T("The merchant's offers changed; nothing was bought.", "La oferta del comerciante cambió; no se compró nada.")
T("The merchant's whole stock in one scrolling list with prices, quality colors and item levels.", "Todo el inventario del comerciante en una lista desplazable con precios, colores de calidad y niveles de objeto.")
T("The minutes below", "Los minutos de abajo")
T("The mouse wheel zooms the map. Middle-click runs the chosen action; left and right clicks keep working as usual.", "La rueda del mouse hace zoom en el mapa. El clic central ejecuta la acción elegida; los clics izquierdo y derecho siguen funcionando como siempre.")
T("The native input box keeps autocomplete, links and chat commands.", "El cuadro de entrada nativo conserva el autocompletado, los enlaces y los comandos de chat.")
T("The normal warning time", "El tiempo de aviso normal")
T("The optional glyph layer changes appearance while Blizzard keeps clicks, tooltips, enabled states and notifications. Queue and FPS indicators stay at Blizzard's Edit Mode position. No recurring MSKIN update runs.", "La capa opcional de glifos cambia el aspecto mientras Blizzard conserva los clics, las descripciones emergentes, los estados de activación y las notificaciones. Los indicadores de cola y de FPS permanecen en su posición del modo de edición de Blizzard. No se ejecuta ninguna actualización periódica de MSKIN.")
T("The options module could not be loaded: %s", "No se pudo cargar el módulo de opciones: %s")
T("The options module did not finish initializing.", "El módulo de opciones no terminó de inicializarse.")
T("The party table grows in steps: characters with build and score, then the combat figures of Blizzard's damage meter, then the loot seen in chat. Each character keeps its latest runs; open the newest here or with /msufruns and step through older ones. Deleting a run asks for a second click. The card can wait until you close the chest's loot window.", "La tabla del grupo crece por pasos: personajes con configuración y puntuación, luego las cifras de combate del medidor de daño de Blizzard y luego el botín visto en el chat. Cada personaje guarda sus últimos recorridos; abre el más reciente aquí o con /msufruns y pasa a los anteriores. Borrar un recorrido pide un segundo clic. La tarjeta puede esperar hasta que cierres la ventana de botín del cofre.")
T("The preview and every section below edit this bar. Shared custom groups start with a separate list for explicit spell, aura and item IDs; disabling sharing restores the existing per-specialization list.", "La vista previa y todas las secciones inferiores editan esta barra. Los grupos personalizados compartidos empiezan con una lista independiente de ID explícitos de hechizos, auras y objetos; al desactivar la opción se restaura la lista existente por especialización.")
T("The preview needs the cooldown manager.", "La vista previa necesita el gestor de reutilización.")
T("The quick switch above remembers this mode when you turn the bar off. Choose Never to keep it hidden.", "El interruptor rápido de arriba recuerda este modo cuando desactivas la barra. Elige Nunca para mantenerla oculta.")
T("The requested quantity is already attached.", "La cantidad solicitada ya está adjunta.")
T("The screenshot shows an example character. Use Layout to preview your module and frame color choices.", "La captura muestra un personaje de ejemplo. Usa Diseño para ver tus módulos y colores de marcos.")
T("The selected WoW macro storage is full", "El almacenamiento de macros de WoW seleccionado está lleno")
T("The socket window is available only in Retail", "La ventana de engarce solo está disponible en Retail")
T("The sound %s is unavailable.", "El sonido %s no está disponible.")
T("The stack condition uses Glow at stacks and Stack comparison. Buff absence cannot drive a combat glow through the native aura-slot API.", "La condición usa Brillo por acumulaciones y Comparación de acumulaciones. La ausencia de un beneficio no puede activar un brillo en combate mediante la API nativa de casillas de aura.")
T("The stack glow is off.", "El resplandor por acumulaciones está desactivado.")
T("The text is too long.", "El texto es demasiado largo.")
T("The waypoint could not be activated.", "No se pudo activar el punto de ruta.")
T("Theme", "Tema")
T("Theme-colored icon outline", "Contorno de icono con el color del tema")
T("Then", "Entonces")
T("There is no named frame under the cursor. Click another spot, or press Escape.", "No hay ningún marco con nombre bajo el cursor. Pulsa en otro sitio o Escape.")
