T("These apply to every bar. The standalone assisted icon follows Blizzard's assisted combat highlight; enable that highlight in the game's Combat options. Its position is available in MSUF Edit Mode. Action bar presses show on cooldown icons only with the MSUF Suite action bars.", "Estos ajustes se aplican a todas las barras. El icono independiente sigue el resaltado de asistencia de combate de Blizzard; actívalo en las opciones de Combate del juego. Su posición se ajusta en el modo de edición de MSUF. Las pulsaciones de la barra de acción solo se muestran en los iconos de reutilización con las barras de acción de MSUF Suite.")
T("These apply to every bar:", "Esto se aplica a todas las barras:")
T("These are dated snapshots. Visit each character and open their bank to refresh its recorded contents.", "Son capturas fechadas. Visita cada personaje y abre su banco para actualizar el contenido registrado.")
T("These choices apply to this spell on every bar and specialization.", "Estas opciones se aplican a este hechizo en todas las barras y especializaciones.")
T("These settings apply to all bars until a bar uses its own style.", "Estos ajustes se aplican a todas las barras hasta que una barra use su propio estilo.")
T("These spells apply to all specializations. Clearing the group empties it for all of them; turning sharing off brings back each spec's own list.", "Estos hechizos se aplican a todas las especializaciones. Vaciar el grupo lo vacía para todas; al desactivar la opción de compartir, vuelve la lista propia de cada especialización.")
