T("Type /keys or /msufkeys to see your own current keystone. Add party, raid or instance to share it in that channel. /keys group requests keys from group members running this Suite helper. The /keys alias is used only when another addon has not claimed it. Inside dungeons and raids Blizzard locks chat for addons; your key is then shown only to you.", "Escribe /keys o /msufkeys para ver tu piedra angular actual. Agrega party, raid o instance para compartirla en ese canal. /keys group solicita las piedras de los miembros del grupo que usan este asistente de Suite. El alias /keys solo se usa si ningún otro addon lo ha reservado. Dentro de calabozos y bandas Blizzard bloquea el chat para los addons; entonces tu piedra solo se te muestra a ti.")
T("Type /msufguildprivacy or use the small ON/OFF button above the main chat window. Any chat window containing Guild or Officer is covered in full, including other channels in a mixed window. The guild chat in the Guild & Communities window can be covered as well; other communities stay visible. Reveal the chat again with the click chosen here. Messages keep arriving underneath.", "Escribe /msufguildprivacy o usa el pequeño botón ON/OFF encima de la ventana principal de chat. Se cubre por completo toda ventana que contenga mensajes de Hermandad u Oficiales, incluidos otros canales de una ventana mixta. También puede cubrirse el chat de hermandad de la ventana Hermandad y comunidades; las demás comunidades siguen visibles. Vuelve a mostrar el chat con el clic elegido aquí. Los mensajes siguen llegando debajo.")
T("Type /msufraid to expand Blizzard's Raid Manager, /msufpull [1-60] for its native countdown, or /msufmark tank or /msufmark healer to mark one unambiguous party member. Optional automatic markers work only for one clear tank or healer in a five-player party, as leader or assistant. Existing and occupied markers are respected. Countdowns, markers and ready checks wait while Blizzard restricts them during combat, encounters and keystones; automatic markers try again afterwards.", "Escribe /msufraid para desplegar el gestor de banda de Blizzard, /msufpull [1-60] para su cuenta regresiva nativa, o /msufmark tank o /msufmark healer para marcar a un único miembro del grupo sin ambigüedad. Las marcas automáticas opcionales solo funcionan con un tanque o sanador claro en un grupo de cinco, como líder o asistente. Se respetan las marcas existentes y ocupadas. Las cuentas regresivas, las marcas y las comprobaciones de preparación esperan mientras Blizzard las restringe en combate, encuentros y piedras angulares; las marcas automáticas vuelven a intentarlo después.")
T("Type /way x y for the current map or /way mapID x y. /msufway always works. The short /way alias is used only when no other addon owns it.", "Escriba /way x y para el mapa actual o /way mapID x y. /msufway siempre funciona. El alias corto /way se utiliza sólo cuando ningún otro complemento lo posee.")
