T("|cff9fc3e7[Guild]|r %s: Welcome to MSUF.", "|cff9fc3e7[Hermandad]|r %s: Bienvenido a MSUF.")
T("|cffc9d4dd[Party]|r Chat links and channels stay native.", "|cffc9d4dd[Grupo]|r Los enlaces y canales del chat se mantienen nativos.")
T("|cffc9d4dd[Raid]|r %s: Pull when %s is ready.", "|cffc9d4dd[Banda]|r %s: Inicia el combate cuando %s esté listo.")
T("• No idle OnUpdate; a window corner drag runs one only while the mouse button is held\n• No repeating tickers; short one-shot timers only batch layout and hover updates\n• One frame walk per session, when the window skin is first enabled, adopts existing panel buttons\n• No aura or nameplate listeners; unit events only for the Micro Bar portrait and open character panels\n• Combat-state events only pause and resume deferred work and close open option popups\n• One shared ADDON_LOADED dispatcher only while catalog targets are pending\n• External weak-key runtime state", "• Sin OnUpdate en reposo; arrastrar una esquina de ventana ejecuta uno solo mientras se mantiene presionado el botón del mouse\n• Sin tickers repetitivos; temporizadores breves de un solo uso solo agrupan actualizaciones de diseño y de paso del cursor\n• Un recorrido de marcos por sesión, al activar por primera vez el skin de ventanas, adopta los botones de panel existentes\n• Sin escuchas de auras ni de placas de nombre; eventos de unidad solo para el retrato del micromenú y los paneles de personaje abiertos\n• Los eventos de estado de combate solo pausan y reanudan el trabajo diferido y cierran las ventanas emergentes de opciones abiertas\n• Un único despachador compartido de ADDON_LOADED solo mientras haya objetivos del catálogo pendientes\n• Estado de ejecución externo con claves débiles")
